wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input this call received, on every call, before anything
        // else can trap.
        state_rw::put("last-input", &feed_url);

        // Clock: the time this heartbeat read.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: the one permitted fetch. A transport failure is a value
        // and counts as zero characters; a host outside the allowlist traps at
        // the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: the message carries only the numbers this node computed,
        // never the fetched text.
        let mut message = String::from("heartbeat: seconds=");
        message.push_str(&seconds.to_string());
        message.push_str(" fetched=");
        message.push_str(&fetched.to_string());

        let notified = notifier::notify(&message);

        // Contract: ensures notified == true. If the notification was not
        // accepted there is no valid output, so trap rather than return a
        // report that breaks (or falsifies) the contract.
        if !notified {
            panic!("heartbeat: notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

